using System.ComponentModel.DataAnnotations;
using WudilFood.Models;
namespace WudilFood.ViewModels;
public class RegisterForm { [Required,MaxLength(100)] public string FullName {get;set;}=""; [Required,EmailAddress] public string Email {get;set;}=""; [Required,Phone] public string Phone {get;set;}=""; [Required,MinLength(10),DataType(DataType.Password)] public string Password {get;set;}=""; [Required] public string Role {get;set;}=Roles.Customer; public string? Address {get;set;} public string? BusinessName {get;set;} public string? Location {get;set;} }
public class LoginForm { [Required,EmailAddress] public string Email {get;set;}=""; [Required] public string Password {get;set;}=""; }
public class ForgotPasswordForm { [Required,EmailAddress] public string Email {get;set;}=""; }
public class ResetPasswordForm { [Required,EmailAddress] public string Email {get;set;}=""; [Required] public string Token {get;set;}=""; [Required,MinLength(10),DataType(DataType.Password)] public string Password {get;set;}=""; [Required,DataType(DataType.Password),Compare(nameof(Password))] public string ConfirmPassword {get;set;}=""; }
public class ItemForm { public int Id {get;set;} [Required,MaxLength(120)] public string Name {get;set;}=""; public string Description {get;set;}=""; [Range(1,10000000)] public decimal Price {get;set;} [Range(0,100000)] public int Stock {get;set;} [Range(1,1440)] public int PreparationMinutes {get;set;}=30; [Required] public int CategoryId {get;set;} public List<IFormFile> Images {get;set;}=new(); public List<string> RemoveImages {get;set;}=new(); public List<string> ExistingImages {get;set;}=new(); public List<string> ImageOrder {get;set;}=new(); public AvailabilityMode Mode {get;set;} public bool IsVisible {get;set;}=true; public DayOfWeek Day {get;set;} public TimeOnly StartsAt {get;set;}=new(8,0); public TimeOnly EndsAt {get;set;}=new(20,0); public TimeOnly OrderDeadline {get;set;}=new(18,0); public int? Capacity {get;set;} }
public class CartEntry { public int ItemId {get;set;} public int Quantity {get;set;} }
public class CheckoutForm { [Required] public DateTime LocalSlot {get;set;} [Required] public Fulfillment Fulfillment {get;set;} [Required] public PaymentMethod PaymentMethod {get;set;} public string? DeliveryAddress {get;set;} public string? Note {get;set;} [MaxLength(100)] public string? GuestName {get;set;} [EmailAddress] public string? GuestEmail {get;set;} [Phone] public string? GuestPhone {get;set;} }
